// ⚙️ SETTINGS — this is the only node you need to edit.
// To add a source, add an item to the matching list. An empty list skips that source.
return [{
  json: {
    // YouTube channels: @handle or a channel ID starting with UC
    youtubeChannels: [
      '@tizeslista_hu',
      'UCjFCzjkgSShdRZIVJx3SSlQ',
    ],

    // X usernames (without the @)
    xAccounts: [
      'ChifoiCristian',
    ],

    // Newsletters: the sender's email address (read from your Gmail account)
    emailSenders: [
      'newsletter@example.com',
    ],

    lookbackHours: 24,       // older content is skipped, even on the first run
    maxItemsPerSource: 5,    // max new items per source per run
    maxCharsPerItem: 12000,  // max characters per item sent to the LLM
    maxImages: 8,            // max X images (charts) sent to the model

    model: 'claude-sonnet-5-5',
    reportLanguage: 'Hungarian',  // language of the summary
    telegramChatId: '-100XXXXXXXXXX',  // channel or chat ID
  },
}];

// One output item per channel. Accepts both @handles and UC... channel IDs.
const cfg = $('⚙️ Settings').first().json;
return (cfg.youtubeChannels || [])
  .map(c => String(c).trim())
  .filter(Boolean)
  .map(c => ({
    json: {
      channel: c,
      lookup: c.startsWith('UC')
        ? `id=${c}`
        : `forHandle=${encodeURIComponent(c.startsWith('@') ? c : '@' + c)}`,
    },
  }));

// Turn playlistItems responses into uniform content items within the lookback window.
const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const out = [];
for (const res of $input.all()) {
  for (const it of res.json.items || []) {
    const s = it.snippet || {};
    const videoId = s.resourceId?.videoId;
    if (!videoId || Date.parse(s.publishedAt) < since) continue;
    out.push({
      json: {
        uid: `youtube:${videoId}`,
        source: 'youtube',
        author: s.channelTitle || '',
        title: s.title || '',
        url: `https://www.youtube.com/watch?v=${videoId}`,
        published: new Date(s.publishedAt).toISOString(),
        text: s.description || '',
        videoId,
      },
    });
  }
}
return out;

// The transcript responses come back in the same order as the input videos.
// Without a transcript (or without a Supadata key) the video description is used.
const videos = $('YouTube: new videos only').all();
return $input.all().map((res, i) => {
  const video = videos[i].json;
  const transcript = typeof res.json.content === 'string' ? res.json.content.trim() : '';
  return {
    json: {
      ...video,
      text: transcript || video.text,
      hasTranscript: Boolean(transcript),
    },
  };
});

const cfg = $('⚙️ Settings').first().json;
return (cfg.xAccounts || [])
  .map(u => String(u).trim().replace(/^@/, ''))
  .filter(Boolean)
  .map(userName => ({ json: { userName } }));

// twitterapi.io response → uniform items. Tweets live under "tweets" or "data.tweets"
// depending on the API version. Images (charts) are passed on as URLs.
const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
const accounts = $('X: accounts').all();
const out = [];
$input.all().forEach((res, i) => {
  const payload = res.json || {};
  const tweets = payload.tweets || payload.data?.tweets || [];
  const user = accounts[i]?.json.userName || '';
  for (const tw of tweets.slice(0, cfg.maxItemsPerSource)) {
    const created = Date.parse(tw.createdAt);
    if (!(created >= since)) continue;
    const media = tw.extendedEntities?.media || tw.entities?.media || [];
    out.push({
      json: {
        uid: `x:${tw.id}`,
        source: 'x',
        author: tw.author?.name ? `${tw.author.name} (@${user})` : `@${user}`,
        title: (tw.text || '').slice(0, 90).replace(/\n/g, ' '),
        url: tw.url || `https://x.com/${user}/status/${tw.id}`,
        published: new Date(created).toISOString(),
        text: tw.text || '',
        images: media.filter(m => m.type === 'photo').map(m => m.media_url_https),
      },
    });
  }
});
return out;

// Gmail search for the senders. With an empty list the newsletter branch is skipped.
const cfg = $('⚙️ Settings').first().json;
const senders = (cfg.emailSenders || []).map(s => String(s).trim()).filter(Boolean);
if (!senders.length) return [];
const days = Math.max(1, Math.ceil(cfg.lookbackHours / 24));
return [{ json: { q: `from:(${senders.join(' OR ')}) newer_than:${days}d` } }];

const cfg = $('⚙️ Settings').first().json;
const since = Date.now() - cfg.lookbackHours * 3600 * 1000;
return $input.all()
  .map(r => r.json)
  .filter(m => m.id && !m.error)
  .filter(m => !m.date || Date.parse(m.date) >= since)
  .map(m => {
    const from = m.from?.value?.[0] || {};
    return {
      json: {
        uid: `email:${m.id}`,
        source: 'email',
        author: from.name || from.address || m.from?.text || '',
        title: m.subject || '(no subject)',
        url: `https://mail.google.com/mail/u/0/#all/${m.id}`,
        published: new Date(m.date || Date.now()).toISOString(),
        text: (m.text || '').trim(),
      },
    };
  });

// One Claude request for all new items: text plus the images from X posts.
const cfg = $('⚙️ Settings').first().json;
const items = $input.all().map(i => i.json).filter(j => j.uid);
if (!items.length) return [];

const LABEL = { youtube: 'YouTube video', x: 'X post', email: 'Newsletter' };
const order = { youtube: 0, x: 1, email: 2 };
items.sort((a, b) =>
  order[a.source] - order[b.source] ||
  a.author.localeCompare(b.author) ||
  a.published.localeCompare(b.published));

const system = `You are a content digest assistant. From the new content of the YouTube
channels, X accounts and newsletters the user follows, you write a summary in
${cfg.reportLanguage} that is sent as a Telegram message.

Rules:
- Group by source, then by author. Each group starts with an emoji and the author's name.
- For each item: a one-line title, then the gist in 2-6 sentences: the main claims, arguments,
  numbers, dates and price levels. If an image contains a chart, read the key levels off it.
- Put the link on its own line at the end of the item.
- Only state what the source says. If only the description of a video was available,
  say so and do not invent its content.
- Plain text, no Markdown (Telegram will not render it here): no **, no #, no tables.
- No introduction or sign-off. If there are several items, a short summary paragraph may close the message.`;

const blocks = items.map((it, n) => {
  const note = it.source === 'youtube' && !it.hasTranscript
    ? '\n(No transcript available, only the video description.)' : '';
  const body = (it.text || '').slice(0, cfg.maxCharsPerItem);
  return `### [${n + 1}] ${LABEL[it.source]} — ${it.author}\nTitle: ${it.title}\n` +
         `Date: ${it.published}\nLink: ${it.url}${note}\n\n${body}`;
});

const content = [{
  type: 'text',
  text: `${items.length} new items:\n\n${blocks.join('\n\n---\n\n')}`,
}];
let imageCount = 0;
items.forEach((it, n) => {
  for (const url of (it.images || []).slice(0, 2)) {
    if (imageCount >= cfg.maxImages) return;
    content.push({ type: 'text', text: `Image for item [${n + 1}]:` });
    content.push({ type: 'image', source: { type: 'url', url } });
    imageCount++;
  }
});

return [{
  json: {
    itemCount: items.length,
    body: {
      model: cfg.model,
      max_tokens: 4000,
      system,
      messages: [{ role: 'user', content }],
    },
  },
}];

// Telegram allows at most 4096 characters per message, so split at paragraph boundaries.
const res = $input.first().json;
const text = (res.content || [])
  .filter(c => c.type === 'text')
  .map(c => c.text)
  .join('\n')
  .trim();
if (!text) throw new Error('Empty Claude response: ' + JSON.stringify(res).slice(0, 500));

const stamp = new Date().toLocaleString('en-GB', { timeZone: 'Europe/Budapest' });
const LIMIT = 3900;
const chunks = [];
let current = `📰 Content Digest — ${stamp}\n\n`;
for (let para of text.split(/\n{2,}/)) {
  if (current.length + para.length + 2 > LIMIT && current.trim()) {
    chunks.push(current.trim());
    current = '';
  }
  while (para.length > LIMIT) {
    chunks.push(para.slice(0, LIMIT));
    para = para.slice(LIMIT);
  }
  current += para + '\n\n';
}
if (current.trim()) chunks.push(current.trim());

return chunks.map((chunk, i) => ({
  json: { chunk: chunks.length > 1 ? `${chunk}\n\n(${i + 1}/${chunks.length})` : chunk },
}));
